function hitBricks(grid: number[][], hits: number[][]): number[] {
    const m = grid.length;
    const n = grid[0].length;
    const roof = m * n;
    const total = roof + 1;

    const parent = new Int32Array(total);
    const size = new Int32Array(total);

    for (let i = 0; i < total; i++) {
        parent[i] = i;
        size[i] = 1;
    }

    const find = (x: number): number => {
        let root = x;

        while (parent[root] !== root) {
            root = parent[root];
        }

        while (parent[x] !== x) {
            const next = parent[x];
            parent[x] = root;
            x = next;
        }

        return root;
    };

    const union = (a: number, b: number): void => {
        let rootA = find(a);
        let rootB = find(b);

        if (rootA === rootB) return;

        if (size[rootA] < size[rootB]) {
            const temp = rootA;
            rootA = rootB;
            rootB = temp;
        }

        parent[rootB] = rootA;
        size[rootA] += size[rootB];
    };

    const removed = new Array<boolean>(hits.length).fill(false);

    for (let i = 0; i < hits.length; i++) {
        const [row, col] = hits[i];

        if (grid[row][col] === 1) {
            removed[i] = true;
            grid[row][col] = 0;
        }
    }

    const id = (row: number, col: number): number => row * n + col;

    for (let row = 0; row < m; row++) {
        for (let col = 0; col < n; col++) {
            if (grid[row][col] === 0) continue;

            const current = id(row, col);

            if (row === 0) {
                union(current, roof);
            }
            if (row > 0 && grid[row - 1][col] === 1) {
                union(current, id(row - 1, col));
            }
            if (col > 0 && grid[row][col - 1] === 1) {
                union(current, id(row, col - 1));
            }
        }
    }

    const result = new Array<number>(hits.length).fill(0);
    const directions = [
        [-1, 0],
        [1, 0],
        [0, -1],
        [0, 1]
    ];

    for (let i = hits.length - 1; i >= 0; i--) {
        if (!removed[i]) continue;

        const [row, col] = hits[i];
        const before = size[find(roof)];
        const current = id(row, col);

        grid[row][col] = 1;

        if (row === 0) {
            union(current, roof);
        }

        for (const [dr, dc] of directions) {
            const nextRow = row + dr;
            const nextCol = col + dc;

            if (
                nextRow >= 0 &&
                nextRow < m &&
                nextCol >= 0 &&
                nextCol < n &&
                grid[nextRow][nextCol] === 1
            ) {
                union(current, id(nextRow, nextCol));
            }
        }

        const after = size[find(roof)];
        result[i] = Math.max(0, after - before - 1);
    }

    return result;
}
