function clumsy(n: number): number {
    const stack: number[] = [n];
    let operation = 0;

    for (let value = n - 1; value >= 1; value--, operation = (operation + 1) % 4) {
        const top = stack.length - 1;

        if (operation === 0) {
            stack[top] *= value;
        } else if (operation === 1) {
            stack[top] = Math.trunc(stack[top] / value);
        } else if (operation === 2) {
            stack.push(value);
        } else {
            stack.push(-value);
        }
    }

    return stack.reduce((sum, value) => sum + value, 0);
};
