class MKAverage {
    private readonly m: number;
    private readonly k: number;
    private readonly maxValue = 100000;

    private countTree: Int32Array;
    private sumTree: Float64Array;

    private queue: number[] = [];
    private head = 0;
    private size = 0;

    constructor(m: number, k: number) {
        this.m = m;
        this.k = k;
        this.countTree = new Int32Array(this.maxValue + 1);
        this.sumTree = new Float64Array(this.maxValue + 1);
    }

    addElement(num: number): void {
        this.queue.push(num);
        this.size++;
        this.update(num, 1);

        if (this.size > this.m) {
            const removed = this.queue[this.head++];
            this.update(removed, -1);
            this.size--;
        }
    }

    calculateMKAverage(): number {
        if (this.size < this.m) {
            return -1;
        }

        const sumThroughUpperBoundary = this.sumSmallest(this.m - this.k);
        const sumThroughLowerBoundary = this.sumSmallest(this.k);
        const middleSum = sumThroughUpperBoundary - sumThroughLowerBoundary;

        return Math.floor(middleSum / (this.m - 2 * this.k));
    }

    private update(value: number, delta: number): void {
        for (let i = value; i <= this.maxValue; i += i & -i) {
            this.countTree[i] += delta;
            this.sumTree[i] += value * delta;
        }
    }

    private sumSmallest(amount: number): number {
        if (amount <= 0) {
            return 0;
        }

        let index = 0;
        let count = 0;
        let sum = 0;
        let step = 1;

        while (step * 2 <= this.maxValue) {
            step *= 2;
        }

        for (; step > 0; step = Math.floor(step / 2)) {
            const next = index + step;

            if (
                next <= this.maxValue &&
                count + this.countTree[next] < amount
            ) {
                index = next;
                count += this.countTree[next];
                sum += this.sumTree[next];
            }
        }

        const boundaryValue = index + 1;
        return sum + (amount - count) * boundaryValue;
    }
}
