function maxScore(nums: number[]): number {
    const length = nums.length;
    const fullMask = (1 << length) - 1;

    const gcd = (a: number, b: number): number => {
        while (b !== 0) {
            const remainder = a % b;
            a = b;
            b = remainder;
        }
        return a;
    };

    const pairGcd: number[][] = Array.from(
        { length },
        () => new Array<number>(length).fill(0)
    );

    for (let i = 0; i < length; i++) {
        for (let j = i + 1; j < length; j++) {
            pairGcd[i][j] = gcd(nums[i], nums[j]);
        }
    }

    const bitCount = new Uint8Array(fullMask + 1);
    for (let mask = 1; mask <= fullMask; mask++) {
        bitCount[mask] = bitCount[mask >> 1] + (mask & 1);
    }

    const dp = new Int32Array(fullMask + 1);
    dp.fill(-1);
    dp[0] = 0;

    for (let mask = 0; mask < fullMask; mask++) {
        if (dp[mask] < 0 || bitCount[mask] % 2 !== 0) continue;

        const operation = bitCount[mask] / 2 + 1;

        for (let i = 0; i < length; i++) {
            if ((mask & (1 << i)) !== 0) continue;

            for (let j = i + 1; j < length; j++) {
                if ((mask & (1 << j)) !== 0) continue;

                const nextMask = mask | (1 << i) | (1 << j);
                const score = dp[mask] + operation * pairGcd[i][j];
                dp[nextMask] = Math.max(dp[nextMask], score);
            }
        }
    }

    return dp[fullMask];
};
