function maximumANDSum(nums: number[], numSlots: number): number {
    const powersOfThree = new Array<number>(numSlots);
    powersOfThree[0] = 1;

    for (let i = 1; i < numSlots; i++) {
        powersOfThree[i] = powersOfThree[i - 1] * 3;
    }

    const stateCount = powersOfThree[numSlots - 1] * 3;
    let dp = new Int32Array(stateCount);
    dp.fill(-1);
    dp[0] = 0;

    for (const num of nums) {
        const next = new Int32Array(stateCount);
        next.fill(-1);

        for (let mask = 0; mask < stateCount; mask++) {
            if (dp[mask] < 0) continue;

            for (let slot = 0; slot < numSlots; slot++) {
                const occupancy = Math.floor(mask / powersOfThree[slot]) % 3;
                if (occupancy >= 2) continue;

                const nextMask = mask + powersOfThree[slot];
                const score = dp[mask] + (num & (slot + 1));

                if (score > next[nextMask]) {
                    next[nextMask] = score;
                }
            }
        }

        dp = next;
    }

    let answer = 0;
    for (const score of dp) {
        answer = Math.max(answer, score);
    }

    return answer;
};
