function maxStudents(seats: string[][]): number {
    const m = seats.length;
    const n = seats[0].length;
    const limit = 1 << n;

    const available: number[] = new Array(m).fill(0);
    for (let row = 0; row < m; row++) {
        for (let col = 0; col < n; col++) {
            if (seats[row][col] === ".") {
                available[row] |= 1 << col;
            }
        }
    }

    const validMasks: number[][] = Array.from({ length: m }, () => []);
    const studentCount: number[] = new Array(limit).fill(0);

    for (let mask = 0; mask < limit; mask++) {
        studentCount[mask] = studentCount[mask >> 1] + (mask & 1);

        if ((mask & (mask << 1)) !== 0) continue;

        for (let row = 0; row < m; row++) {
            if ((mask & ~available[row]) === 0) {
                validMasks[row].push(mask);
            }
        }
    }

    let previous = new Array<number>(limit).fill(-1);
    previous[0] = 0;

    for (let row = 0; row < m; row++) {
        const current = new Array<number>(limit).fill(-1);

        for (const mask of validMasks[row]) {
            for (let prevMask = 0; prevMask < limit; prevMask++) {
                if (previous[prevMask] < 0) continue;
                if ((mask & (prevMask << 1)) !== 0) continue;
                if ((mask & (prevMask >> 1)) !== 0) continue;

                current[mask] = Math.max(
                    current[mask],
                    previous[prevMask] + studentCount[mask]
                );
            }
        }

        previous = current;
    }

    return Math.max(...previous);
}
