function licenseKeyFormatting(s: string, k: number): string {
    const cleaned = s.replace(/-/g, "").toUpperCase();

    if (cleaned.length === 0) {
        return "";
    }

    const groups: string[] = [];
    let index = cleaned.length % k;

    if (index > 0) {
        groups.push(cleaned.slice(0, index));
    }

    while (index < cleaned.length) {
        groups.push(cleaned.slice(index, index + k));
        index += k;
    }

    return groups.join("-");
};
