function maxCompatibilitySum(students: number[][], mentors: number[][]): number {
    const m = students.length;
    const n = students[0].length;
    const compatibility: number[][] = Array.from(
        { length: m },
        () => Array(m).fill(0)
    );

    for (let student = 0; student < m; student++) {
        for (let mentor = 0; mentor < m; mentor++) {
            for (let question = 0; question < n; question++) {
                if (students[student][question] === mentors[mentor][question]) {
                    compatibility[student][mentor]++;
                }
            }
        }
    }

    const size = 1 << m;
    const dp: number[] = Array(size).fill(-Infinity);
    const bitCount: number[] = Array(size).fill(0);
    dp[0] = 0;

    for (let mask = 1; mask < size; mask++) {
        bitCount[mask] = bitCount[mask >> 1] + (mask & 1);
    }

    for (let mask = 0; mask < size; mask++) {
        const student = bitCount[mask];
        if (student >= m) continue;

        for (let mentor = 0; mentor < m; mentor++) {
            if ((mask & (1 << mentor)) === 0) {
                const nextMask = mask | (1 << mentor);
                dp[nextMask] = Math.max(
                    dp[nextMask],
                    dp[mask] + compatibility[student][mentor]
                );
            }
        }
    }

    return dp[size - 1];
};
