function minDays(n: number): number {
    const memo = new Map<number, number>();

    const dfs = (oranges: number): number => {
        if (oranges <= 1) return oranges;
        if (memo.has(oranges)) return memo.get(oranges)!;

        const days = 1 + Math.min(
            oranges % 2 + dfs(Math.floor(oranges / 2)),
            oranges % 3 + dfs(Math.floor(oranges / 3))
        );

        memo.set(oranges, days);
        return days;
    };

    return dfs(n);
};
