function numOfWays(nums: number[]): number {
    const MOD = 1000000007n;
    const n = nums.length;

    const modPow = (base: bigint, exponent: bigint): bigint => {
        let result = 1n;
        while (exponent > 0n) {
            if (exponent & 1n) {
                result = (result * base) % MOD;
            }
            base = (base * base) % MOD;
            exponent >>= 1n;
        }
        return result;
    };

    const factorial: bigint[] = new Array(n + 1).fill(1n);
    const inverseFactorial: bigint[] = new Array(n + 1).fill(1n);

    for (let i = 1; i <= n; i++) {
        factorial[i] = (factorial[i - 1] * BigInt(i)) % MOD;
    }

    inverseFactorial[n] = modPow(factorial[n], MOD - 2n);
    for (let i = n; i >= 1; i--) {
        inverseFactorial[i - 1] =
            (inverseFactorial[i] * BigInt(i)) % MOD;
    }

    const choose = (total: number, selected: number): bigint => {
        return (
            factorial[total] *
            inverseFactorial[selected] %
            MOD *
            inverseFactorial[total - selected]
        ) % MOD;
    };

    const countWays = (values: number[]): bigint => {
        if (values.length <= 2) return 1n;

        const left: number[] = [];
        const right: number[] = [];
        const root = values[0];

        for (let i = 1; i < values.length; i++) {
            if (values[i] < root) {
                left.push(values[i]);
            } else {
                right.push(values[i]);
            }
        }

        const interleavings = choose(values.length - 1, left.length);
        return (
            interleavings *
            countWays(left) %
            MOD *
            countWays(right)
        ) % MOD;
    };

    return Number((countWays(nums) - 1n + MOD) % MOD);
};
