function friendRequests(n: number, restrictions: number[][], requests: number[][]): boolean[] {
    const parent: number[] = Array.from({ length: n }, (_, i) => i);
    const size: number[] = new Array(n).fill(1);

    const find = (x: number): number => {
        while (x !== parent[x]) {
            parent[x] = parent[parent[x]];
            x = parent[x];
        }
        return x;
    };

    const union = (a: number, b: number): void => {
        a = find(a);
        b = find(b);

        if (a === b) return;

        if (size[a] < size[b]) {
            [a, b] = [b, a];
        }

        parent[b] = a;
        size[a] += size[b];
    };

    const result: boolean[] = [];

    for (const [u, v] of requests) {
        const rootU = find(u);
        const rootV = find(v);

        if (rootU === rootV) {
            result.push(true);
            continue;
        }

        let valid = true;

        for (const [x, y] of restrictions) {
            const rootX = find(x);
            const rootY = find(y);

            if (
                (rootX === rootU && rootY === rootV) ||
                (rootX === rootV && rootY === rootU)
            ) {
                valid = false;
                break;
            }
        }

        result.push(valid);

        if (valid) {
            union(rootU, rootV);
        }
    }

    return result;
};
