function minSessions(tasks: number[], sessionTime: number): number {
    const n = tasks.length;
    const totalMasks = 1 << n;

    const sessions = new Int16Array(totalMasks);
    const usedTime = new Int16Array(totalMasks);
    sessions.fill(n + 1);
    usedTime.fill(sessionTime + 1);

    sessions[0] = 1;
    usedTime[0] = 0;

    for (let mask = 0; mask < totalMasks; mask++) {
        for (let i = 0; i < n; i++) {
            const bit = 1 << i;
            if ((mask & bit) !== 0) continue;

            const nextMask = mask | bit;
            let nextSessions = sessions[mask];
            let nextUsedTime: number;

            if (usedTime[mask] + tasks[i] <= sessionTime) {
