function removeInvalidParentheses(s: string): string[] {
    let leftRemove = 0;
    let rightRemove = 0;

    for (const char of s) {
        if (char === "(") {
            leftRemove++;
        } else if (char === ")") {
            if (leftRemove > 0) {
                leftRemove--;
            } else {
                rightRemove++;
            }
        }
    }

    const n = s.length;
    const suffixOpen = new Array<number>(n + 1).fill(0);
    const suffixClose = new Array<number>(n + 1).fill(0);

    for (let i = n - 1; i >= 0; i--) {
        suffixOpen[i] = suffixOpen[i + 1] + (s[i] === "(" ? 1 : 0);
        suffixClose[i] = suffixClose[i + 1] + (s[i] === ")" ? 1 : 0);
    }

    const result = new Set<string>();
    const path: string[] = [];

    const dfs = (
        index: number,
        balance: number,
        removeOpen: number,
        removeClose: number
    ): void => {
        if (
            removeOpen > suffixOpen[index] ||
            removeClose > suffixClose[index] ||
            balance > suffixClose[index] - removeClose
        ) {
            return;
        }

        if (index === n) {
            if (balance === 0 && removeOpen === 0 && removeClose === 0) {
                result.add(path.join(""));
            }
            return;
        }

        const char = s[index];

        if (char === "(") {
            if (removeOpen > 0) {
                dfs(index + 1, balance, removeOpen - 1, removeClose);
            }

            path.push(char);
            dfs(index + 1, balance + 1, removeOpen, removeClose);
            path.pop();
        } else if (char === ")") {
            if (removeClose > 0) {
                dfs(index + 1, balance, removeOpen, removeClose - 1);
            }

            if (balance > 0) {
                path.push(char);
                dfs(index + 1, balance - 1, removeOpen, removeClose);
                path.pop();
            }
        } else {
            path.push(char);
            dfs(index + 1, balance, removeOpen, removeClose);
            path.pop();
        }
    };

    dfs(0, 0, leftRemove, rightRemove);
    return Array.from(result);
}
