        () => Array(26).fill(0)
    );
    const prefix2: number[][] = Array.from(
        { length: n + 1 },
        () => Array(26).fill(0)
    );

    for (let i = 0; i < n; i++) {
        for (let c = 0; c < 26; c++) {
            prefix1[i + 1][c] = prefix1[i][c];
            prefix2[i + 1][c] = prefix2[i][c];
        }
        prefix1[i + 1][s1.charCodeAt(i) - 97]++;
        prefix2[i + 1][s2.charCodeAt(i) - 97]++;
    }

    const memo = new Int8Array(n * n * (n + 1));

    const haveSameCharacters = (i: number, j: number, length: number): boolean => {
        for (let c = 0; c < 26; c++) {
            const count1 = prefix1[i + length][c] - prefix1[i][c];
            const count2 = prefix2[j + length][c] - prefix2[j][c];
            if (count1 !== count2) return false;
        }
        return true;
    };

    const dfs = (i: number, j: number, length: number): boolean => {
        const key = (i * n + j) * (n + 1) + length;
