        let identical = true;
        for (let k = 0; k < length; k++) {
            if (s1.charCodeAt(i + k) !== s2.charCodeAt(j + k)) {
                identical = false;
                break;
            }
        }

        if (identical) {
            memo[key] = 2;
            return true;
        }

        if (!haveSameCharacters(i, j, length)) {
            memo[key] = 1;
            return false;
        }

        for (let split = 1; split < length; split++) {
            if (
                dfs(i, j, split) &&
                dfs(i + split, j + split, length - split)
