function medianSlidingWindow(nums: number[], k: number): number[] {
    const sorted = nums.slice().sort((a, b) => a - b);
    const values: number[] = [];

    for (const value of sorted) {
        if (values.length === 0 || values[values.length - 1] !== value) {
            values.push(value);
        }
    }

    const indices = new Map<number, number>();
    for (let i = 0; i < values.length; i++) {
        indices.set(values[i], i + 1);
    }

    const tree = new Int32Array(values.length + 1);

    const update = (index: number, delta: number): void => {
        while (index < tree.length) {
            tree[index] += delta;
            index += index & -index;
        }
    };

    const kth = (rank: number): number => {
        let index = 0;
        let step = 1;

        while (step * 2 <= values.length) {
            step *= 2;
        }

        while (step > 0) {
            const next = index + step;
            if (next <= values.length && tree[next] < rank) {
                index = next;
                rank -= tree[next];
            }
            step = Math.floor(step / 2);
        }

        return values[index];
    };

    const result: number[] = [];
    const leftRank = Math.floor((k + 1) / 2);
    const rightRank = Math.floor((k + 2) / 2);

    for (let i = 0; i < nums.length; i++) {
        update(indices.get(nums[i])!, 1);

        if (i >= k) {
            update(indices.get(nums[i - k])!, -1);
        }

        if (i >= k - 1) {
            result.push((kth(leftRank) + kth(rightRank)) / 2);
        }
    }

    return result;
};
