function splitArray(nums: number[], k: number): number {
    let left = 0;
    let right = 0;

    for (const num of nums) {
        left = Math.max(left, num);
        right += num;
    }

    while (left < right) {
        const mid = Math.floor(left + (right - left) / 2);
        let subarrays = 1;
        let currentSum = 0;

        for (const num of nums) {
            if (currentSum + num > mid) {
                subarrays++;
                currentSum = num;
            } else {
                currentSum += num;
            }
        }

        if (subarrays <= k) {
            right = mid;
        } else {
            left = mid + 1;
        }
    }

    return left;
};
