    const result: number[] = [start];
    let previous: number | null = null;
    let current = start;
    const n = adjacentPairs.length + 1;

    while (result.length < n) {
        const neighbors = graph.get(current)!;
        const next = neighbors[0] !== previous ? neighbors[0] : neighbors[1];

        result.push(next);
        previous = current;
        current = next;
    }

    return result;
};
