function earliestAndLatest(n: number, firstPlayer: number, secondPlayer: number): number[] {
    const memo = new Map<string, number[]>();
    const BASE = 32;

    function dfs(m: number, a: number, b: number): number[] {
        if (a + b === m + 1) {
            return [1, 1];
        }

        const key = `${m},${a},${b}`;
        const cached = memo.get(key);
        if (cached !== undefined) {
            return cached;
        }

        let states = new Set<number>([0]);

        const category = (position: number): number => {
            if (position < a) return BASE;
            if (position > a && position < b) return 1;
            return 0;
        };

        const processMatch = (left: number, right?: number): void => {
            let deltas: number[];

            if (right === undefined) {
                deltas = [category(left)];
            } else if (left === a || right === a || left === b || right === b) {
                deltas = [0];
            } else {
                deltas = [category(left), category(right)];
            }

            const nextStates = new Set<number>();
            for (const state of states) {
                for (const delta of deltas) {
                    nextStates.add(state + delta);
                }
            }
            states = nextStates;
        };

        for (let left = 1; left <= Math.floor(m / 2); left++) {
            processMatch(left, m + 1 - left);
        }

        if (m % 2 === 1) {
            processMatch(Math.floor(m / 2) + 1);
        }

        const nextSize = Math.ceil(m / 2);
        let earliest = Infinity;
        let latest = -Infinity;

        for (const state of states) {
            const beforeA = Math.floor(state / BASE);
            const between = state % BASE;
            const nextA = beforeA + 1;
            const nextB = beforeA + between + 2;

            const [childEarliest, childLatest] = dfs(nextSize, nextA, nextB);
            earliest = Math.min(earliest, childEarliest + 1);
            latest = Math.max(latest, childLatest + 1);
        }

        const result = [earliest, latest];
        memo.set(key, result);
        return result;
    }

    return dfs(n, firstPlayer, secondPlayer);
};
