function getCoprimes(nums: number[], edges: number[][]): number[] {
    const n = nums.length;
    const graph: number[][] = Array.from({ length: n }, () => []);

    for (const [u, v] of edges) {
        graph[u].push(v);
        graph[v].push(u);
    }

    const gcd = (a: number, b: number): number => {
        while (b !== 0) {
            const remainder = a % b;
            a = b;
            b = remainder;
        }
        return a;
    };

    const coprimeValues: number[][] = Array.from({ length: 51 }, () => []);
    for (let a = 1; a <= 50; a++) {
        for (let b = 1; b <= 50; b++) {
            if (gcd(a, b) === 1) {
                coprimeValues[a].push(b);
            }
        }
    }

    const ans = new Array<number>(n).fill(-1);
    const depth = new Int32Array(n);
    const valueStacks: number[][] = Array.from({ length: 51 }, () => []);

    valueStacks[nums[0]].push(0);

    const nodeStack: number[] = [0];
    const parentStack: number[] = [-1];
    const nextEdgeStack: number[] = [0];

    while (nodeStack.length > 0) {
        const frame = nodeStack.length - 1;
        const node = nodeStack[frame];

        if (nextEdgeStack[frame] === graph[node].length) {
            valueStacks[nums[node]].pop();
            nodeStack.pop();
            parentStack.pop();
            nextEdgeStack.pop();
            continue;
        }

        const child = graph[node][nextEdgeStack[frame]++];
        if (child === parentStack[frame]) {
            continue;
        }

        depth[child] = depth[node] + 1;

        let closestNode = -1;
        let closestDepth = -1;

        for (const value of coprimeValues[nums[child]]) {
            const stack = valueStacks[value];
            if (stack.length === 0) continue;

            const ancestor = stack[stack.length - 1];
            if (depth[ancestor] > closestDepth) {
                closestDepth = depth[ancestor];
                closestNode = ancestor;
            }
        }

        ans[child] = closestNode;
        valueStacks[nums[child]].push(child);

        nodeStack.push(child);
        parentStack.push(node);
        nextEdgeStack.push(0);
    }

    return ans;
};
