function kWeakestRows(mat: number[][], k: number): number[] {
    const rows = mat.map((row, index) => {
        let left = 0;
        let right = row.length;

        while (left < right) {
            const mid = left + Math.floor((right - left) / 2);

            if (row[mid] === 1) {
                left = mid + 1;
            } else {
                right = mid;
            }
        }

        return { index, soldiers: left };
    });

    rows.sort((a, b) =>
        a.soldiers !== b.soldiers
            ? a.soldiers - b.soldiers
            : a.index - b.index
    );

    return rows.slice(0, k).map(row => row.index);
};
