function strWithout3a3b(a: number, b: number): string {
    const result: string[] = [];

    while (a > 0 || b > 0) {
        const n = result.length;
        const hasTwoA = n >= 2 && result[n - 1] === 'a' && result[n - 2] === 'a';
        const hasTwoB = n >= 2 && result[n - 1] === 'b' && result[n - 2] === 'b';

        if (hasTwoA) {
            result.push('b');
            b--;
        } else if (hasTwoB) {
            result.push('a');
            a--;
        } else if (a >= b && a > 0) {
            result.push('a');
            a--;
        } else {
            result.push('b');
            b--;
        }
    }

    return result.join('');
}
