function validateBinaryTreeNodes(n: number, leftChild: number[], rightChild: number[]): boolean {
    const inDegree = new Array<number>(n).fill(0);

    for (let i = 0; i < n; i++) {
        const left = leftChild[i];
        const right = rightChild[i];

        if (left !== -1 && ++inDegree[left] > 1) return false;
        if (right !== -1 && ++inDegree[right] > 1) return false;
    }

    let root = -1;

    for (let i = 0; i < n; i++) {
        if (inDegree[i] === 0) {
            if (root !== -1) return false;
            root = i;
        }
    }

    if (root === -1) return false;

    const visited = new Array<boolean>(n).fill(false);
    const stack: number[] = [root];
    let count = 0;

    while (stack.length > 0) {
        const node = stack.pop()!;

        if (visited[node]) return false;
        visited[node] = true;
        count++;

        if (leftChild[node] !== -1) stack.push(leftChild[node]);
        if (rightChild[node] !== -1) stack.push(rightChild[node]);
    }

    return count === n;
};
