function ladderLength(beginWord: string, endWord: string, wordList: string[]): number {
    const dictionary = new Set<string>(wordList);

    if (!dictionary.has(endWord)) {
        return 0;
    }

    const queue: string[] = [beginWord];
    dictionary.delete(beginWord);

    let head = 0;
    let sequenceLength = 1;

    while (head < queue.length) {
        const levelSize = queue.length - head;

        for (let i = 0; i < levelSize; i++) {
            const word = queue[head++];
            const letters = word.split("");

            for (let position = 0; position < letters.length; position++) {
                const originalLetter = letters[position];

                for (let code = 97; code <= 122; code++) {
                    const nextLetter = String.fromCharCode(code);

                    if (nextLetter === originalLetter) {
                        continue;
                    }

                    letters[position] = nextLetter;
                    const nextWord = letters.join("");

                    if (nextWord === endWord) {
                        return sequenceLength + 1;
                    }

                    if (dictionary.has(nextWord)) {
                        dictionary.delete(nextWord);
                        queue.push(nextWord);
                    }
                }

                letters[position] = originalLetter;
            }
        }

        sequenceLength++;
    }

    return 0;
}
